public class IntervalDomain implements Domain<State> {

    public static class Interval {
        BigInteger min, max;
        boolean isBottom;

        public Interval(BigInteger min, BigInteger max) {
            this.min = min;
            this.max = max;
            this.isBottom = false;
        }

        public static Interval top() {
            return new Interval(BigInteger.valueOf(Long.MIN_VALUE), BigInteger.valueOf(Long.MAX_VALUE));
        }

        public static Interval bottom() {
            Interval i = new Interval(BigInteger.valueOf(1), BigInteger.valueOf(0));
            i.isBottom = true;
            return i;
        }

        public boolean isBottom() {
            return isBottom || min.compareTo(max) > 0;
        }

        public Interval intersect(Interval other) {
            if (this.isBottom() || other.isBottom()) return bottom();
            BigInteger newMin = min.max(other.min);
            BigInteger newMax = max.min(other.max);
            if (newMin.compareTo(newMax) > 0) return bottom();
            return new Interval(newMin, newMax);
        }

        public Interval widen(Interval other) {
            if (this.isBottom()) return other;
            if (other.isBottom()) return this;
            BigInteger newMin = min.min(other.min);
            BigInteger newMax = max.max(other.max);
            return new Interval(newMin, newMax);
        }
    }

    public static class State {
        Map<String, Interval> vars = new HashMap<>();

        public Interval getVar(String name) {
            return vars.getOrDefault(name, Interval.top());
